package org.example;

import com.sun.jna.Function;
import com.sun.jna.Native;
import com.sun.jna.Pointer;
import com.sun.jna.ptr.FloatByReference;
import com.sun.jna.ptr.PointerByReference;
import com.sun.jna.platform.win32.Guid;
import com.sun.jna.platform.win32.Ole32;
import com.sun.jna.platform.win32.WinNT;

public class CoreAudioVolume {

    // CLSID MMDeviceEnumerator
    private static final Guid.CLSID CLSID_MMDeviceEnumerator =
            new Guid.CLSID(&quot;{BCDE0395-E52F-467C-8E3D-C4579291692E}&quot;);

    // IID IMMDeviceEnumerator
    private static final Guid.IID IID_IMMDeviceEnumerator =
            new Guid.IID(&quot;{A95664D2-9614-4F35-A746-DE8DB63617E6}&quot;);

    // IID IAudioEndpointVolume
    private static final Guid.IID IID_IAudioEndpointVolume =
            new Guid.IID(&quot;{5CDF2C82-841E-4546-9722-0CF74078229A}&quot;);

    // CLSCTX_ALL
    private static final int CLSCTX_ALL = 23;

    // vtable indexes (including IUnknown methods at 0..2)
    private static final int IMMDEVICEENUM_GETDEFAULTAUDIOENDPOINT = 4;
    private static final int IMMDEVICE_ACTIVATE = 3;
    private static final int IUNKNOWN_RELEASE = 2;
    private static final int IAudioEndpointVolume_GetMasterVolumeLevelScalar = 9;

    public static float getMasterVolumeScalar() {
        WinNT.HRESULT hr = Ole32.INSTANCE.CoInitializeEx(Pointer.NULL, Ole32.COINIT_MULTITHREADED);
        int hrVal = hr.intValue();
        boolean coInitialized = hrVal &gt;= 0; // success (S_OK or S_FALSE) =&gt; non-negative
        if (hrVal &lt; 0) {
            throw new RuntimeException(&quot;CoInitializeEx failed: 0x&quot; + Integer.toHexString(hrVal));
        }

        PointerByReference pEnumeratorRef = new PointerByReference();
        hr = Ole32.INSTANCE.CoCreateInstance(CLSID_MMDeviceEnumerator, null, CLSCTX_ALL, IID_IMMDeviceEnumerator, pEnumeratorRef);
        hrVal = hr.intValue();
        if (hrVal &lt; 0) {
            if (coInitialized) Ole32.INSTANCE.CoUninitialize();
            throw new RuntimeException(&quot;CoCreateInstance(MMDeviceEnumerator) failed: 0x&quot; + Integer.toHexString(hrVal));
        }

        Pointer pEnumerator = pEnumeratorRef.getValue();
        try {
            // GetDefaultAudioEndpoint(eRender=0, eConsole=0, &amp;pDevice)
            PointerByReference pDeviceRef = new PointerByReference();
            invokeComMethodInt(pEnumerator, IMMDEVICEENUM_GETDEFAULTAUDIOENDPOINT,
                    new Object[]{pEnumerator, 0, 0, pDeviceRef});

            Pointer pDevice = pDeviceRef.getValue();
            try {
                // Activate IID_IAudioEndpointVolume on the device
                PointerByReference pEndpointVolumeRef = new PointerByReference();
                invokeComMethodInt(pDevice, IMMDEVICE_ACTIVATE,
                        new Object[]{pDevice, IID_IAudioEndpointVolume, CLSCTX_ALL, Pointer.NULL, pEndpointVolumeRef});

                Pointer pEndpointVolume = pEndpointVolumeRef.getValue();
                try {
                    // Call GetMasterVolumeLevelScalar(float* pfLevel)
                    FloatByReference level = new FloatByReference();
                    invokeComMethodInt(pEndpointVolume, IAudioEndpointVolume_GetMasterVolumeLevelScalar,
                            new Object[]{pEndpointVolume, level});

                    return level.getValue(); // 0.0 .. 1.0
                } finally {
                    release(pEndpointVolume);
                }
            } finally {
                release(pDevice);
            }
        } finally {
            release(pEnumerator);
            Ole32.INSTANCE.CoUninitialize();
        }
    }

    private static void invokeComMethodInt(Pointer comObject, int vtableIndex, Object[] args) {
        Pointer fnPtr = getVTableFunctionPointer(comObject, vtableIndex);
        int res = Function.getFunction(fnPtr, Function.ALT_CONVENTION).invokeInt(args);
        if (res &lt; 0) {
            throw new RuntimeException(&quot;COM call failed at vtable index &quot; + vtableIndex + &quot;: 0x&quot; + Integer.toHexString(res));
        }
    }

    private static Pointer getVTableFunctionPointer(Pointer comObject, int vtableIndex) {
        Pointer vTablePtr = comObject.getPointer(0);
        long offset = (long) vtableIndex * Native.POINTER_SIZE;
        return vTablePtr.getPointer(offset);
    }

    private static void release(Pointer comObject) {
        if (comObject == null) return;
        Pointer fn = getVTableFunctionPointer(comObject, IUNKNOWN_RELEASE);
        Function.getFunction(fn, Function.ALT_CONVENTION).invokeInt(new Object[]{comObject});
    }

    public static void main(String[] args) {
        float scalar = getMasterVolumeScalar();
        System.out.printf(&quot;Master volume: %.2f%% (scalar=%.6f)%n&quot;, scalar * 100f, scalar);
    }
}
// java
package org.example;

import com.sun.jna.platform.win32.User32;
import com.sun.jna.platform.win32.WinDef;
import com.sun.jna.platform.win32.WinDef.HWND;

public class VolumeControl {
    private static final int WM_APPCOMMAND = 0x0319;
    private static final int APPCOMMAND_VOLUME_DOWN = 0x09;
    private static final int APPCOMMAND_VOLUME_MUTE = 0x08;
    private static final int APPCOMMAND_VOLUME_UP = 0x0A;

    // New: send an app-command to the foreground window. The command code is encoded
    // in the high-order 16 bits of lParam per WM_APPCOMMAND contract.
    public static void sendAppCommand(int appCommand) {
        HWND hwnd = User32.INSTANCE.GetForegroundWindow();
        WinDef.LPARAM lParam = new WinDef.LPARAM(((long) appCommand) &lt;&lt; 16);
        User32.INSTANCE.SendMessage(hwnd, WM_APPCOMMAND, new WinDef.WPARAM(0), lParam);
    }

    // New: convenience methods
    public static void volumeUp() {
        sendAppCommand(APPCOMMAND_VOLUME_UP);
    }

    public static void volumeDown() {
        sendAppCommand(APPCOMMAND_VOLUME_DOWN);
    }

    public static void muteToggle() {
        sendAppCommand(APPCOMMAND_VOLUME_MUTE);
    }

    public static void main(String[] args) {
        // existing demo logic preserved: simulate down, mute, up as example
        HWND hwnd = User32.INSTANCE.GetForegroundWindow();

        WinDef.LPARAM lParamDown = new WinDef.LPARAM((long) APPCOMMAND_VOLUME_DOWN &lt;&lt; 16);
        User32.INSTANCE.SendMessage(hwnd, WM_APPCOMMAND, new WinDef.WPARAM(0), lParamDown);

        WinDef.LPARAM lParamMute = new WinDef.LPARAM((long) APPCOMMAND_VOLUME_MUTE &lt;&lt; 16);
        User32.INSTANCE.SendMessage(hwnd, WM_APPCOMMAND, new WinDef.WPARAM(0), lParamMute);

        WinDef.LPARAM lParamVolumeUp = new WinDef.LPARAM((long) APPCOMMAND_VOLUME_UP &lt;&lt; 16);
        User32.INSTANCE.SendMessage(hwnd, WM_APPCOMMAND, new WinDef.WPARAM(0), lParamVolumeUp);

        // Note: this class only simulates media key presses; use CoreAudioVolume
        // for precise numeric volume queries/changes.
    }
}
package org.example;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

@RestController
@RequestMapping(&quot;/api/volume&quot;)
public class VolumeRestController {

    // GET /api/volume
    @GetMapping
    public ResponseEntity&lt;Map&lt;String, Object&gt;&gt; getVolume() {
        try {
            float scalar = CoreAudioVolume.getMasterVolumeScalar();
            int percent = Math.round(scalar * 100f);
            return ResponseEntity.ok(Map.of(&quot;scalar&quot;, scalar, &quot;percent&quot;, percent));
        } catch (Exception e) {
            return ResponseEntity.status(500).body(Map.of(&quot;error&quot;, e.getMessage()));
        }
    }

    // POST /api/volume?action={up|down|mute}
    // Single endpoint to perform volume actions. Keeps API surface smaller.
    @PostMapping
    public ResponseEntity&lt;Map&lt;String, Object&gt;&gt; action(@RequestParam String action) {
        try {
            switch (action.toLowerCase()) {
                case &quot;up&quot;:
                    VolumeControl.volumeUp();
                    break;
                case &quot;down&quot;:
                    VolumeControl.volumeDown();
                    break;
                case &quot;mute&quot;:
                    VolumeControl.muteToggle();
                    break;
                default:
                    return ResponseEntity.badRequest().body(Map.of(&quot;error&quot;, &quot;unknown action&quot;));
            }
            return ResponseEntity.ok(Map.of(&quot;status&quot;, &quot;ok&quot;, &quot;action&quot;, action.toLowerCase()));
        } catch (Exception e) {
            return ResponseEntity.status(500).body(Map.of(&quot;error&quot;, e.getMessage()));
        }
    }
}
